class ProductViewHelper {
  formatPrice(product: Product): string {
    return `$${(product.priceCents / 100).toFixed(2)}`;
  }
  truncateDescription(product: Product, maxLength = 100): string {
    return product.description.length > maxLength
      ? product.description.slice(0, maxLength) + "..."
      : product.description;
  }
}

const helper = new ProductViewHelper();

// Template only describes layout, never computes anything itself
function renderProduct(product: Product) {
  return `<div>${helper.formatPrice(product)} — ${helper.truncateDescription(product)}</div>`;
}
